contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking inputs: target address and value to send from C
    function run(address target, uint value) public payable {
        // no precondition on inputs
        // record observable state before calling sendMoney
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        // call sendMoney as this contract (which is not the original deployer/owner)
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observables after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        // General invariant: calling sendMoney by a non-owner cannot change owner, depositsCount, or increase contract balance
        // (It may decrease balance if the call succeeded and money sent out, but it must not increase.)
        assert(ownerBefore == ownerAfter && depositsBefore == depositsAfter && balanceAfter <= balanceBefore);
    }

    // receive to accept Ether if needed by the test harness
    receive() external payable {}
}

